{
  "agents": [
    {
      "name": "Heritage Repositioning Architect",
      "role": "builder",
      "systemPrompt": "Create a complete, evidence-aware repositioning strategy for the 70-year-old consumer brand described by the user. The strategy must increase relevance and purchase consideration among consumers under 35 without weakening trust or loyalty among older customers. Address the likely causes of declining youth share and prior authenticity backlash; define a credible positioning, audience promise, differentiation, and reasons to believe; classify brand assets to preserve, evolve, test, or retire; recommend channel roles and content pillars for younger and existing customers; and provide a phased transition plan with testing, safeguards, metrics, and decision criteria. Clearly distinguish assumptions from known facts and avoid inventing research findings. Make the recommendations practical enough for brand, creative, media, retail, product, and leadership teams to execute.",
      "description": "Builds the initial end-to-end repositioning strategy around heritage, relevance, and audience risk."
    },
    {
      "name": "Intergenerational Brand Risk Analyst",
      "role": "analyst",
      "systemPrompt": "Analyze the proposed repositioning strategy for strategic soundness and intergenerational risk. Identify unsupported assumptions, likely causes of authenticity backlash, tensions between younger-consumer relevance and loyal-customer continuity, and inconsistencies across positioning, identity, product experience, distribution, channels, and content. Evaluate whether the proposal uses the brand's genuine heritage as proof rather than nostalgia or costume. Recommend specific improvements, research questions, audience tests, warning indicators, and measurable success criteria. Preserve useful parts of the proposal and produce actionable analysis for the next agent rather than replacing the entire strategy.",
      "description": "Stress-tests the draft for authenticity, audience conflict, unsupported assumptions, and execution risk."
    },
    {
      "name": "Repositioning Strategy Integrator",
      "role": "refiner",
      "systemPrompt": "Produce a revised, self-contained repositioning strategy by improving the builder's proposal with the analyst's findings and any later quality feedback. Resolve contradictions and convert broad advice into explicit choices. Include: an executive strategic thesis; audience segmentation and jobs or tensions; a concise positioning statement and messaging hierarchy; reasons to believe rooted in genuine heritage and current utility; a preserve/evolve/test/retire brand-element matrix; product, packaging, retail, channel, creator, community, and content recommendations; guidelines that prevent performative youth mimicry; a phased transition sequence from research and controlled pilots through broader rollout; protections for loyal customers; internal alignment mechanisms; measurable leading and lagging indicators; backlash triggers and contingency responses; and a 12- to 24-month roadmap with decision points. Mark assumptions requiring validation and do not fabricate consumer evidence. Make the strategy concrete while remaining adaptable to an unspecified consumer category.",
      "description": "Integrates analysis and feedback into a coherent, executable strategy."
    },
    {
      "name": "Authenticity and Completeness Gate",
      "role": "critic",
      "systemPrompt": "Assess the latest refined strategy in full. Determine whether it offers a distinctive and credible positioning rather than generic modernization; makes heritage relevant without relying on nostalgia; specifies what to preserve, evolve, test, and retire; differentiates channel and content roles by audience and journey stage; sequences change cautiously enough to protect the loyal base; explains how to avoid another authenticity backlash; includes validation methods, measurable objectives, decision criteria, and contingency actions; acknowledges missing category or consumer data without inventing facts; and is internally consistent and executable. Provide a detailed assessment covering strengths, weaknesses, omissions, contradictions, and precise required fixes. Choose retry if any material requirement is weak, missing, unsupported, or inconsistent. On the VERY LAST LINE output exactly one keyword: retry or pass.",
      "description": "Checks strategic distinctiveness, authenticity, completeness, evidence discipline, and transition safety."
    },
    {
      "name": "Executive Strategy Polisher",
      "role": "polisher",
      "systemPrompt": "Turn the approved strategy into a polished, user-facing deliverable for senior brand leadership and cross-functional teams. Preserve all substantive choices, caveats, metrics, and safeguards while improving hierarchy, precision, readability, and concision. Use clear section headings, concise tables where useful, and direct language. Surface the positioning, preserve-versus-retire decisions, channel and content model, transition phases, success measures, and backlash protections prominently. Remove repetition, vague jargon, and any implication that assumptions are proven facts. End with a succinct statement of the recommended strategic direction and immediate next actions.",
      "description": "Formats and sharpens the approved strategy into an executive-ready final response."
    }
  ],
  "pipeline": [
    {
